-- =====================================================================
-- khaustan_lookup_data_seed_KhaustanRestaurantMenu.sql
-- Lookup / reference data for: service_mode, protein_type,
-- delivery_provider, platform_tag, price_schedule, auth_provider
-- Target: PostgreSQL (KhaustanRestaurantMenu )
-- =====================================================================
--
-- CONVENTIONS USED IN THIS FILE
-- 1. Primary keys are application-assigned BIGINTs in this schema
--    (no SERIAL/IDENTITY column) -- every ID below is an explicit
--    literal, never generated by Postgres.
-- 2. Every INSERT carries ON CONFLICT ... DO NOTHING against the
--    table's natural business key (code / tag_code / provider_code),
--    so this file is safe to run more than once. price_schedule has
--    no such unique business key today, so it falls back to
--    conflicting on its primary key instead -- see the note in that
--    section.
-- 3. SECTION 1 is data you told me is already live. It is commented
--    out on purpose -- it is here for documentation/version-control
--    only, so a future migration file has a record of what these IDs
--    mean. Uncomment only if you are seeding a fresh environment that
--    does not have this data yet.
-- 4. SECTION 2 is proposed starter data for the three lookup tables
--    that don't have data yet. It is left uncommented and ready to
--    run, but the IDs are just my suggested starting values (plain
--    1, 2, 3, ...) -- protein_type's real IDs (900001+, 920007+)
--    show you already use a block-allocation convention elsewhere,
--    so swap these for whatever range your ID allocator actually
--    assigns before running this in a real environment.
-- =====================================================================


\connect :"DBname"
-- ---------------------------------------------------------------------
-- service_mode  |  last service_mode_id currently in use = 6
-- ---------------------------------------------------------------------
 INSERT INTO service_mode (service_mode_id, code, name, is_active)
 VALUES
     (1, 'dine_in',       'Dine-in',         TRUE),
     (2, 'drive_through', 'Drive-through',   TRUE),
     (3, 'takeaway',      'Takeaway',        TRUE),
     (4, 'delivery',      'Delivery',        TRUE),
     (5, 'bulk_catering', 'Bulk / Catering', TRUE),
     (6, 'room_service',  'Room Service',    TRUE)
 ON CONFLICT (code) DO NOTHING;

-- ---------------------------------------------------------------------
-- protein_type  |  code is always UPPER CASE
-- NOTE: the IDs you gave have gaps -- 900004-900006 and 920001-920006
-- are not among them. Inserting exactly what was supplied below, not
-- guessing at what fills the gap.
-- ---------------------------------------------------------------------
 INSERT INTO protein_type (protein_type_id, code, label)
 VALUES
     (900001, 'CHICKEN', 'Chicken'),
     (900002, 'MUTTON',  'Mutton'),
     (900003, 'SEAFOOD', 'Seafood'),
     (920007, 'BEEF',    'Beef'),
     (920008, 'PORK',    'Pork'),
     (920009, 'EGG',     'Egg'),
     (920010, 'OTHER',   'Other')
 ON CONFLICT (code) DO NOTHING;

-- ---------------------------------------------------------------------
-- delivery_provider  |  code is always UPPER CASE
-- FLAG: Dunzo shut down its consumer delivery service in Jan 2025 and
-- is currently in insolvency proceedings (as of mid-2026) -- it is not
-- a live delivery option. Row kept below with is_active = FALSE so
-- historical menu_item_delivery / order records still resolve
-- correctly; don't route new orders to it.
-- ---------------------------------------------------------------------
 INSERT INTO delivery_provider
     (delivery_provider_id, provider_code, provider_name,provider_type_code, is_active)
 VALUES
     (1, 'ZOMATO', 'Zomato',         'third_party', TRUE),
     (2, 'SWIGGY', 'Swiggy',         'third_party', TRUE),
     (3, 'DUNZO',  'Dunzo',          'third_party', FALSE),
     (4, 'SELF',   'Self Delivery',  'self',        TRUE)
 ON CONFLICT (provider_code) DO NOTHING;


-- #####################################################################
-- SECTION 2 -- PROPOSED STARTER DATA (no existing data given; ready
-- to run as-is, review the ID ranges first)
-- #####################################################################

BEGIN;

