-- ---------------------------------------------------------------------
-- price_schedule  |  6 common named pricing windows.
-- NOTE: "Late Night" ends before it starts (23:00 -> 02:00) because it
-- crosses midnight -- make sure whatever reads this does a wraparound
-- check (end_time < start_time means "spans midnight"), not a plain
-- BETWEEN start_time AND end_time.
-- NOTE: day-of-week restrictions (e.g. Weekend Brunch = Sat/Sun only)
-- belong in price_schedule_day, one row per applicable day, added
-- separately -- not included here since it wasn't asked for.
-- NOTE: price_schedule has no UNIQUE constraint on name today, so
-- this ON CONFLICT targets the primary key instead of a business key
-- -- worth adding a UNIQUE constraint on name if that's not intentional.
-- ---------------------------------------------------------------------
INSERT INTO price_schedule(price_schedule_id, name, description, start_time, end_time, is_active)
VALUES
    (1, 'Breakfast',      'Morning breakfast pricing window',                '06:00', '11:00', TRUE),
    (2, 'Lunch',          'Midday lunch pricing window',                     '12:00', '15:30', TRUE),
    (3, 'Happy Hour',     'Discounted early-evening drinks/appetiser window','17:00', '19:00', TRUE),
    (4, 'Dinner',         'Evening dinner pricing window',                   '19:00', '23:00', TRUE),
    (5, 'Late Night',     'Post-dinner window, spans midnight',              '23:00', '02:00', TRUE),
    (6, 'Weekend Brunch', 'Saturday-Sunday brunch window',                   '10:00', '15:00', TRUE)
ON CONFLICT (price_schedule_id) DO NOTHING;

